    function automatic logic [1:0] nx_of(input logic [1:0] x);
        nx_of = (x == 2'd0) ? 2'd2 : ((x == 2'd2) ? 2'd1 : 2'd0);
    endfunction
    function automatic logic [1:0] scr_of(input logic [1:0] x);
        scr_of = (x == 2'd0) ? 2'd1 : ((x == 2'd1) ? 2'd2 : 2'd0);
