            4'd0: gap_of = 4'd12;
            4'd1: gap_of = 4'd13;
            4'd2: gap_of = 4'd15;
            4'd3: gap_of = 4'd12;
            4'd4: gap_of = 4'd13;
            4'd5: gap_of = 4'd15;
            4'd6: gap_of = 4'd12;
            4'd7: gap_of = 4'd13;
            4'd8: gap_of = 4'd15;
            4'd9: gap_of = 4'd12;
            4'd10: gap_of = 4'd13;
            4'd11: gap_of = 4'd15;
            default: gap_of = '0;
        endcase
    end
    always_ff @(posedge clk) begin
        if (rst) begin
            fset <= 2'd0; fptr <= '0; full <= '0; busy <= '0; res <= '0;
            cact <= 1'b0; cset <= 2'd0; cnext <= 2'd0; s <= '0; tau <= '0; gap <= '0;
            dact <= 1'b0; dset <= 2'd0; dnext <= res_of(2'd0); dptr <= '0; dsr <= '0;
            for (int i = 0; i < 19; i++) dsrs[i] <= 2'd0;
        end else begin
            if (acc) begin
                fptr <= flast ? '0 : fptr + 1'b1;
                if (flast) begin full[fset] <= 1'b1; busy[res_of(fset)] <= 1'b1; fset <= nx_of(fset); end
            end
            dsr <= {dsr[17:0], clast}; dsrs[0] <= res_of(cset);
            for (int i = 1; i < 19; i++) dsrs[i] <= dsrs[i-1];
            if (startc) begin
                full[cnext] <= 1'b0;
                cact <= 1'b1; cset <= cnext; cnext <= nx_of(cnext); s <= '0; tau <= '0; gap <= '0;
            end else if (clast) cact <= 1'b0;
            else if (issue) begin
                if (tlast) begin gap <= gap_of; s <= s + 1'b1; tau <= '0; end
                else tau <= tau + 1'b1;
            end else if (cact && gap != '0) gap <= gap - 1'b1;
            if (done) begin busy[done_set] <= 1'b0; res[done_set] <= 1'b1; end
            if (dlastb) res[dset] <= 1'b0;
            if (startd) begin dact <= 1'b1; dset <= dnext; dnext <= nx_of(dnext); dptr <= '0; end
            else if (dlastb) dact <= 1'b0;
            else if (dact) dptr <= dptr + 1'b1;
